import { TabContext, TabList, TabPanel } from "@mui/lab";
import {
  Box,
  Container,
  createTheme,
  Fade,
  Grid,
  styled,
  Tab,
  Typography,
  useMediaQuery,
} from "@mui/material";
import React from "react";
import { useState } from "react";
import managementIcon from "../../../../assets/images/managementIcon.svg";
import managementActiveIcon from "../../../../assets/images/managementActive.svg";
import reportsIcon from "../../../../assets/images/reports.svg";
import reportsActiveIcon from "../../../../assets/images/reportsActive.svg";
import delegationWorkflowIcon from "../../../../assets/images/delegationWorkflow.svg";
import delegationActiveIcon from "../../../../assets/images/delegationActive.svg";
import automationIcon from "../../../../assets/images/automation.svg";
import automationActiveIcon from "../../../../assets/images/automationActive.svg";
import backupIcon from "../../../../assets/images/backup.svg";
import backupActiveIcon from "../../../../assets/images/backupActive.svg";
import ADManagerCards from "./ADManagerCards";
import "../../../../styles/animation.css";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import { toastError } from "src/utils/utils";
import { useEffect } from "react";
import { useParams } from "react-router-dom";
import FallbackSpinner from "src/@core/components/spinner";

const ADManager = (props) => {
  const { featuresValue, featuresTitle, itSolutionFeatures, subFeaturesData } =
    props;
  const CustomTab = styled(Tab)(({ theme }) => ({
    fontSize: "14px",
    [theme.breakpoints.down("sm")]: {
      fontSize: "14px",
    },
    [theme.breakpoints.up("md")]: {
      fontSize: "18px",
    },
    [theme.breakpoints.up("lg")]: {
      fontSize: "18px",
    },
    fontWeight: 600,
    lineHeight: "28px",
    textTransform: "capitalize",
    textWrap: "wrap",
    whiteSpace: "normal",
  }));
  const CustomTabPanel = styled(TabPanel)(({ theme }) => ({
    [theme.breakpoints.down("sm")]: {
      padding: 0,
    },
    [theme.breakpoints.up("sm")]: {
      padding: "25px",
    },
  }));
  const [value, setValue] = useState("");
  const handleChange = (event, newValue) => {
    setValue(newValue);
  };
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  const isTablet = useMediaQuery("(min-width:1100px) and (max-width:1400px)");
  const isLarge = useMediaQuery(theme.breakpoints.up("lg"));
  useEffect(() => {
    setValue(featuresValue);
  }, [featuresValue]);
  return (
    <>
      <Container maxWidth={"xl"} sx={{ px: { xs: 5, sm: 10, lg: 15, xl: 20 } }}>
        <Grid container rowGap={10}>
          <Grid item xs={12} sx={{ display: "flex", justifyContent: "center" }}>
            <Typography
              sx={{
                fontSize: {
                  xs: "26px",
                  sm: "28px",
                  md: "38px",
                  lg: "48px",
                },
                lineHeight: {
                  xs: "34px",
                  sm: "50px",
                  md: "60px",
                  lg: "73px",
                },
                fontWeight: 500,
                color: "#201D28",
                textAlign: "center",
                wordBreak: "break-word",
                whiteSpace: "normal",
              }}
              className="fade-in-up-whoweare"
            >
              {/* ADManager Plus Features */}
              {featuresTitle?.title}
            </Typography>
          </Grid>
          {itSolutionFeatures.length > 0 && (
            <Grid item xs={12}>
              <Box
              // sx={{ width: "100%" }}
              >
                <TabContext value={value}>
                  <Box
                    sx={{
                      borderBottom:
                        itSolutionFeatures && itSolutionFeatures.length > 0
                          ? 1
                          : 0,
                      borderColor: "divider",
                    }}
                  >
                    <TabList
                      variant={
                        isMobile
                          ? itSolutionFeatures.length >= 4
                            ? "scrollable"
                            : "fullWidth"
                          : isTablet
                          ? itSolutionFeatures.length >= 10
                            ? "scrollable"
                            : "fullWidth"
                          : isLarge
                          ? itSolutionFeatures.length >= 12
                            ? "scrollable"
                            : "fullWidth"
                          : "fullWidth" // Fallback in case none of the conditions match
                      }
                      onChange={handleChange}
                      aria-label="lab API tabs example"

                      // sx={{
                      //   "& .MuiTabs-flexContainer": {
                      //     display: "flex",
                      //     justifyContent: "space-between",
                      //   },
                      // }}
                    >
                      {itSolutionFeatures?.map((item, index) => (
                        <CustomTab
                          key={index}
                          icon={
                            item?.icon_image && (
                              <Box
                                sx={{
                                  height: { xs: "20px", sm: "29px" },
                                  width: { xs: "20px", sm: "29px" },
                                }}
                              >
                                <img
                                  src={item.icon_image}
                                  alt="icon"
                                  style={{ height: "100%", width: "100%" }}
                                />
                              </Box>
                            )
                          }
                          iconPosition="top"
                          label={item.title}
                          value={item.title}
                          wrapped
                          sx={{
                            color: "inherit", // Keep default color for all states
                            "&.Mui-selected": {
                              color: "inherit", // Prevent color change for active tab
                              textAlign: "start",
                            },
                          }}
                        />
                      ))}
                    </TabList>
                  </Box>
                  {itSolutionFeatures.map((item, index) => (
                    <Fade in={value === item.title} timeout={1000} key={index}>
                      <CustomTabPanel value={item.title}>
                        <ADManagerCards
                          features={subFeaturesData[item.title] || []}
                          //  value="management"
                        />
                      </CustomTabPanel>
                    </Fade>
                  ))}
                </TabContext>
              </Box>
            </Grid>
          )}
        </Grid>
      </Container>
    </>
  );
};

export default ADManager;
