import React, { useState } from "react";
import { useEffect } from "react";
import { useLocation, useParams } from "react-router-dom";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import ADManager from "src/views/pages/ITSolutionDetails/ITSolutionFeatures/ADManager";
import ADManagerList from "src/views/pages/ITSolutionDetails/ITSolutionFeatures/ADManagerList";
import { toastError, toastSuccess } from "src/utils/utils";
import { Box } from "@mui/material";
import bgImg from "../../../assets/images/section1BgImg.png";
import bgImgSmall from "../../../assets/images/bannerSectionBgImgSmall.png";
import "../../../styles/animation.css";
import { useAuth } from "src/hooks/useAuth";
import FallbackSpinner from "src/@core/components/spinner";

const ITSolutionFeaturesPage = () => {
  const { setITSolutionId, setSlug } = useAuth();
  const [loading, setLoading] = useState(false);
  const [featuresTitle, setFeaturesTitle] = useState({});
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();
  const name = id.split("-").slice(0, -1).join("-");
  const [backgroundPositionY, setBackgroundPositionY] = useState(0);
  const [featuresValue, setFeaturesValue] = useState("");
  const [itSolutionFeatures, setItSolutionFeatures] = useState([]);
  const [subFeaturesData, setSubFeaturesData] = useState([]);

  const [subAdditionalFeatures, setSubAdditionalFeatures] = useState([]);
  const [subAdditionalFeaturesList, setSubAdditionalFeaturesList] = useState(
    []
  );
  const [subFeaturesValue, setSubFeaturesValue] = useState("");

  const cleanAndCapitalizeName = (str) =>
    str
      .replace(/-+/g, " ") // Replace one or more hyphens with a single space
      .trim() // Remove leading or trailing spaces
      .replace(/\b\w/g, (char) => char.toUpperCase());

  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
    setITSolutionId(itSolutionId);
    setSlug(name);
    document.title = `DWIT ${cleanAndCapitalizeName(name)}'s Features`;
  }, []);

  //animation
  useEffect(() => {
    const handleScroll = () => {
      const offset = window.pageYOffset || document.documentElement.scrollTop;
      setBackgroundPositionY(offset);
    };

    let animationFrameId;
    const onScroll = () => {
      animationFrameId = requestAnimationFrame(handleScroll);
    };

    window.addEventListener("scroll", onScroll);

    return () => {
      window.removeEventListener("scroll", onScroll);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  const fetchFeaturesTitle = () => {
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_FEATURES_TITLE.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        responseData.map((item) => {
          setFeaturesTitle(item);
        });
      })
      .catch((error) => {
        toastError(error);
      });
  };

  const fetchItSolutionFeatures = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_FEATURES.list(itSolutionId))
      .then((response) => {
        setItSolutionFeatures(response.data.data);
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setFeaturesValue(responseData[0].title);
        }
        responseData.map((item) => {
          fetchITSolutionSubFeatures(item.id, item.title);
        });
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchITSolutionSubFeatures = (id, title) => {
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_SUB_FEATURES.list(id))
      .then((response) => {
        const responseData = response.data.data;
        setSubFeaturesData((prevData) => ({
          ...prevData,
          [title]: responseData,
        }));
      })

      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchSubAdditionalFeatures = () => {
    axiosInstance
      .get(ApiEndpoints.SUB_ADDITIONAL_FEATURES.list(itSolutionId))
      .then((response) => {
        setSubAdditionalFeatures(response.data.data);
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setSubFeaturesValue(responseData[0].title);
        }
        responseData.map((item) => {
          fetchSubAdditionalFeaturesList(item.id, item.title);
        });
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchSubAdditionalFeaturesList = (id, title) => {
    axiosInstance
      .get(ApiEndpoints.SUB_ADDITIONAL_FEATURES_LIST.list(id))
      .then((response) => {
        const responseData = response.data.data;
        setSubAdditionalFeaturesList((prevData) => ({
          ...prevData,
          [title]: responseData,
        }));
      })

      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchFeaturesTitle();
    fetchItSolutionFeatures();
    fetchSubAdditionalFeatures();
  }, [itSolutionId]);

  if (loading) return <FallbackSpinner />;

  return (
    <>
      <Box
        sx={{
          position: "relative",
          minHeight: "100vh",
          overflowX: "hidden",
          overflowY: "auto",
          scrollBehavior: "smooth",
          transition: "2s ease-in-out",
        }}
      >
        <Box
          sx={{
            backgroundImage: { xs: `url(${bgImgSmall})`, sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `right ${backgroundPositionY}px`,
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            zIndex: -1,
            pointerEvents: "none",
            transition: "background-position 1.5s ease-in-out",
          }}
        />
        {featuresTitle && (
          <ADManager
            featuresValue={featuresValue}
            featuresTitle={featuresTitle}
            itSolutionFeatures={itSolutionFeatures}
            subFeaturesData={subFeaturesData}
          />
        )}
        {subAdditionalFeatures.length > 0 && (
          <ADManagerList
            subFeaturesValue={subFeaturesValue}
            subAdditionalFeatures={subAdditionalFeatures}
            subAdditionalFeaturesList={subAdditionalFeaturesList}
          />
        )}
      </Box>
    </>
  );
};

export default ITSolutionFeaturesPage;
